import java.applet.Applet;import java.awt.Graphics;import java.awt.event.*;
@SuppressWarnings("removal") public class MouseClickApplet extends Applet implements MouseListener { private String message="Click inside the applet";public void init(){addMouseListener(this);}public void paint(Graphics g){g.drawString(message,40,60);}public void mouseClicked(MouseEvent e){message="Clicked at "+e.getX()+", "+e.getY();repaint();}public void mousePressed(MouseEvent e){}public void mouseReleased(MouseEvent e){}public void mouseEntered(MouseEvent e){}public void mouseExited(MouseEvent e){} }
